/// prime_fib returns n-th number that is a Fibonacci number and it's also prime.
/// >>> prime_fib(1)
/// 2
/// >>> prime_fib(2)
/// 3
/// >>> prime_fib(3)
/// 5
/// >>> prime_fib(4)
/// 13
/// >>> prime_fib(5)
/// 89
fn prime_fib(n: isize) -> isize {
    if n <= 0 {
        return 0;
    }

    let mut a: u64 = 0;
    let mut b: u64 = 1;
    let mut count: u64 = 0;

    while count < n {
        let next = a + b;
        if is_prime(next) {
            count += 1;
            if count == n {
                return next as isize;
            }
        }
        a = b;
        b = next;
    }

    0
}

fn is_prime(num: u64) -> bool {
    if num < 2 {
        return false;
    }
    if num == 2 {
        return true;
    }
    if num % 2 == 0 {
        return false;
    }
    let limit = (num as f64).sqrt() as u64;
    for i in (3..=limit).step_by(2) {
        if num % i == 0 {
            return false;
        }
    }
    true
}
