def sum_common_divisors(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    common = gcd(a, b)
    sum_div = 0
    for i in range(1, common + 1):
        if common % i == 0:
            sum_div += i
    return sum_div
