/// Find the shortest palindrome that begins with a supplied string.
/// Algorithm idea is simple:
/// - Find the longest postfix of supplied string that is a palindrome.
/// - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
/// >>> make_palindrome(String::from(""))
/// String::from("")
/// >>> make_palindrome(String::from("cat"))
/// String::from("catac")
/// >>> make_palindrome(String::from("cata"))
/// String::from("catac")
fn make_palindrome(string: String) -> String {
    let s = string.as_bytes();
    let n = s.len();
    if n == 0 {
        return string;
    }

    let mut i = n;
    while i > 0 {
        if is_palindrome(s, i) {
            break;
        }
        i -= 1;
    }

    let prefix_len = n - i;
    let mut result = String::with_capacity(n + prefix_len);
    result.push_str(&string);
    let prefix = &string[..prefix_len];
    result.push_str(&prefix.chars().rev().collect::<String>());
    result
}

fn is_palindrome(s: &[u8], start: usize) -> bool {
    let end = s.len() - start;
    if end == 0 {
        return true;
    }
    let mut left = start;
    let mut right = s.len() - 1;
    while left < right {
        if s[left] != s[right] {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}
