/// Write a function to perform index wise addition of vector elements in the given two nested vectors.
fn add_nested_tuples(test_tup1: Vec<Vec<isize>>, test_tup2: Vec<Vec<isize>>) -> Vec<Vec<isize>> {
    let mut result = Vec::new();
    let len = std::cmp::min(test_tup1.len(), test_tup2.len());

    for i in 0..len {
        let mut row = Vec::new();
        let len_row = std::cmp::min(test_tup1[i].len(), test_tup2[i].len());

        for j in 0..len_row {
            row.push(test_tup1[i][j] + test_tup2[i][j]);
        }
        result.push(row);
    }

    result
}
