/// Write a function that takes in positive integers m and n and finds the number of possible sequences of length n, such that each element is a positive integer and is greater than or equal to twice the previous element but less than or equal to m.
fn get_total_number_of_sequences(m: isize, n: isize) -> isize {
    if n == 0 {
        return 0;
    }
    if m < 1 {
        return 0;
    }

    let mut dp: Vec<Vec<isize>> = vec![vec![0; (m + 1) as usize]; (n + 1) as usize];

    // Base case: sequences of length 1
    for i in 1..=m {
        dp[1][i as usize] = 1;
    }

    // Fill DP table
    for len in 2..=n {
        for end_val in 1..=m {
            let mut count = 0;
            for prev_val in 1..=end_val / 2 {
                count += dp[len - 1][prev_val as usize];
            }
            dp[len][end_val as usize] = count;
        }
    }

    // Sum up all sequences of length n
    let mut total = 0;
    for i in 1..=m {
        total += dp[n as usize][i as usize];
    }

    total
}
