/// Write a function to find the longest common subsequence for the given three string sequence. https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/
fn lcs_of_three(X: String, Y: String, Z: String) -> isize {
    let x: Vec<char> = X.chars().collect();
    let y: Vec<char> = Y.chars().collect();
    let z: Vec<char> = Z.chars().collect();

    let n = x.len();
    let m = y.len();
    let k = z.len();

    // Create a 3D DP table
    let mut dp = vec![vec![vec![0; k + 1]; m + 1]; n + 1];

    // Build the DP table
    for i in 1..=n {
        for j in 1..=m {
            for l in 1..=k {
                if x[i - 1] == y[j - 1] && x[i - 1] == z[l - 1] {
                    dp[i][j][l] = 1 + dp[i - 1][j - 1][l - 1];
                } else {
                    dp[i][j][l] = dp[i - 1][j][l].max(dp[i][j - 1][l].max(dp[i][j][l - 1]));
                }
            }
        }
    }

    dp[n][m][k] as isize
}
